async function fetchResource(path) {
  const candidates = [path, `../${path}`, `../../${path}`, `/${path}`];
  for (const url of candidates) {
    try {
      const res = await fetch(url);
      if (res.ok) return res;
    } catch {}
  }
  throw new Error(`找不到資源：${path}`);
}

